package br.com.sussmartcare.notification.infrastructure; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="processed_events") public class ProcessedEvent{@Id private UUID eventId;@Column(nullable=false)private String consumerName;@Column(nullable=false)private Instant processedAt;protected ProcessedEvent(){}public ProcessedEvent(UUID e,String c){eventId=e;consumerName=c;processedAt=Instant.now();}}
